/**
 * Format Discord Rich Embed
 * Formats the qualified lead and Gemini pitch into a structured Discord embed
 */
const lead = $json;
const config = $('Config').first()?.json || { owner: 'octocat', repo: 'Hello-World' };

const payload = {
  username: 'Lead Sniper Bot',
  avatar_url: 'https://cdn-icons-png.flaticon.com/512/3242/3242257.png',
  embeds: [
    {
      title: `🎯 High-Value GitHub Lead: @${lead.login}`,
      url: lead.html_url || `https://github.com/${lead.login}`,
      color: 3066993, // 0x2ECC71 (Emerald Green)
      author: {
        name: `${lead.name || lead.login} (@${lead.login})`,
        url: lead.html_url || `https://github.com/${lead.login}`,
        icon_url: lead.avatar_url || ''
      },
      thumbnail: {
        url: lead.avatar_url || ''
      },
      description: `💡 **AI Lead Angle:**\n${lead.ai_pitch}`,
      fields: [
        {
          name: '🏢 Company',
          value: lead.company && lead.company !== 'Not specified' ? lead.company : 'Not specified',
          inline: true
        },
        {
          name: '👥 Followers',
          value: String(lead.followers ?? 0),
          inline: true
        },
        {
          name: '📦 Public Repos',
          value: String(lead.public_repos ?? 0),
          inline: true
        },
        {
          name: '📍 Location',
          value: lead.location && lead.location !== 'Remote / Unspecified' ? lead.location : 'Remote / Unspecified',
          inline: true
        },
        {
          name: '📝 Bio',
          value: lead.bio && lead.bio !== 'Not specified' ? lead.bio : 'No bio provided',
          inline: false
        }
      ],
      footer: {
        text: `Lead Sniper • Target: ${config.owner}/${config.repo}`
      },
      timestamp: new Date().toISOString()
    }
  ]
};

return [{
  json: {
    ...lead,
    discord_payload: payload
  }
}];

/**
 * Audit Log & State Confirmation Node
 * Confirms delivery of lead and logs audit record
 */
const lead = $('Format Discord Embed').first().json;
return [{
  json: {
    status: 'NOTIFIED',
    dispatched_at: new Date().toISOString(),
    lead_id: lead.id,
    login: lead.login,
    followers: lead.followers,
    public_repos: lead.public_repos,
    company: lead.company,
    ai_pitch: lead.ai_pitch
  }
}];
